"""
PredictionTracker — Langflow Custom Component (Stage 3, v2)
============================================================
Fitur baru:
- Multi-source price fallback: Yahoo → Stooq → Alpha Vantage
- Kuota Alpha Vantage tracking (25/hari free tier)
- Deduplikasi harian (replace/merge/skip)
- Zero external dependencies (stdlib only)
"""

from __future__ import annotations

import csv
import io
import json
import os
import statistics
import time
import urllib.error
import urllib.parse
import urllib.request
import uuid
from datetime import datetime, timezone, timedelta
from pathlib import Path

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, IntInput, Output, StrInput
from lfx.schema import Data, Message


_DEFAULT_STORAGE = os.path.expanduser("~/.langflow_osint_predictions.json")
_DEFAULT_QUOTA_FILE = os.path.expanduser("~/.langflow_alphavantage_quota.json")
_UA = "Mozilla/5.0 (compatible; PredictionTracker/2.0)"
_ALPHA_VANTAGE_DAILY_LIMIT = 25


# ============================================================================
# HELPERS
# ============================================================================

def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _parse_iso(s: str):
    try:
        return datetime.fromisoformat(s.replace("Z", "+00:00"))
    except (ValueError, TypeError):
        return None


def _load_store(path: str) -> dict:
    p = Path(path)
    if not p.exists():
        return {"predictions": [], "metrics": {}}
    try:
        with p.open("r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {"predictions": [], "metrics": {}}
        data.setdefault("predictions", [])
        data.setdefault("metrics", {})
        return data
    except (json.JSONDecodeError, OSError):
        return {"predictions": [], "metrics": {}}


def _save_store(path: str, store: dict) -> None:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(p.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as f:
        json.dump(store, f, indent=2, ensure_ascii=False, default=str)
    tmp.replace(p)


# ============================================================================
# PRICE FETCHERS (multi-source)
# ============================================================================

def _fetch_yahoo(symbol: str) -> float | None:
    """Yahoo Finance chart API. Primary source."""
    url = (
        f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}"
        f"?range=5d&interval=1d"
    )
    req = urllib.request.Request(url, headers={"User-Agent": _UA})
    try:
        with urllib.request.urlopen(req, timeout=8) as resp:
            payload = json.loads(resp.read(1024 * 1024).decode("utf-8", errors="replace"))
        result = payload["chart"]["result"][0]
        closes = result["indicators"]["quote"][0].get("close") or []
        clean = [c for c in closes if c is not None and c > 0]
        return float(clean[-1]) if clean else None
    except Exception:
        return None


def _fetch_stooq(symbol: str) -> float | None:
    """Stooq CSV download. Backup 1 (no API key, no quota)."""
    # Stooq pakai format: xom.us, aapl.us, brk-b.us (lowercase, dash→dash)
    stooq_symbol = symbol.lower().replace(".", "-")
    url = (
        f"https://stooq.com/q/l/?s={stooq_symbol}.us"
        f"&f=sd2t2ohlcv&h&e=csv"
    )
    req = urllib.request.Request(url, headers={"User-Agent": _UA})
    try:
        with urllib.request.urlopen(req, timeout=8) as resp:
            text = resp.read(64 * 1024).decode("utf-8", errors="replace")
        reader = csv.DictReader(io.StringIO(text))
        for row in reader:
            close_val = (row.get("Close") or "").strip()
            if close_val and close_val.upper() != "N/D":
                try:
                    return float(close_val)
                except ValueError:
                    continue
    except Exception:
        return None
    return None


def _load_quota(path: str) -> dict:
    p = Path(path)
    if not p.exists():
        return {"date": "", "count": 0}
    try:
        with p.open("r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, OSError):
        return {"date": "", "count": 0}


def _save_quota(path: str, quota: dict) -> None:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("w", encoding="utf-8") as f:
        json.dump(quota, f)


def _check_quota(quota_path: str) -> tuple[bool, dict]:
    """Cek apakah kuota Alpha Vantage masih tersedia hari ini."""
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    quota = _load_quota(quota_path)
    if quota.get("date") != today:
        quota = {"date": today, "count": 0}
        _save_quota(quota_path, quota)
    available = quota["count"] < _ALPHA_VANTAGE_DAILY_LIMIT
    return available, quota


def _increment_quota(quota_path: str) -> None:
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    quota = _load_quota(quota_path)
    if quota.get("date") != today:
        quota = {"date": today, "count": 0}
    quota["count"] = quota.get("count", 0) + 1
    _save_quota(quota_path, quota)


def _fetch_alpha_vantage(symbol: str, api_key: str, quota_path: str) -> float | None:
    """Alpha Vantage GLOBAL_QUOTE. Backup 2 (kuota terbatas)."""
    if not api_key:
        return None
    available, _ = _check_quota(quota_path)
    if not available:
        return None
    params = urllib.parse.urlencode({
        "function": "GLOBAL_QUOTE",
        "symbol": symbol,
        "apikey": api_key,
    })
    url = f"https://www.alphavantage.co/query?{params}"
    req = urllib.request.Request(url, headers={"User-Agent": _UA})
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            payload = json.loads(resp.read(256 * 1024).decode("utf-8", errors="replace"))
        _increment_quota(quota_path)  # hit quota bahkan jika response kosong
        quote = payload.get("Global Quote") or {}
        price_str = quote.get("05. price")
        if price_str:
            return float(price_str)
    except Exception:
        _increment_quota(quota_path)
        return None
    return None


# Wrapper cache untuk menghindari fetch berulang
_PRICE_CACHE: dict[str, tuple[float | None, float]] = {}
_PRICE_CACHE_TTL = 600


def fetch_price_with_fallback(
    symbol: str,
    alpha_vantage_key: str,
    quota_path: str,
) -> tuple[float | None, str]:
    """
    Return: (price, source)
    Urutan: Yahoo → Stooq → Alpha Vantage
    """
    cache_key = symbol.upper()
    cached = _PRICE_CACHE.get(cache_key)
    if cached and time.time() < cached[1]:
        return cached[0], "cache"

    price = _fetch_yahoo(symbol)
    if price is not None:
        _PRICE_CACHE[cache_key] = (price, time.time() + _PRICE_CACHE_TTL)
        return price, "yahoo"

    price = _fetch_stooq(symbol)
    if price is not None:
        _PRICE_CACHE[cache_key] = (price, time.time() + _PRICE_CACHE_TTL)
        return price, "stooq"

    price = _fetch_alpha_vantage(symbol, alpha_vantage_key, quota_path)
    if price is not None:
        _PRICE_CACHE[cache_key] = (price, time.time() + _PRICE_CACHE_TTL)
        return price, "alpha_vantage"

    return None, "none"


# ============================================================================
# DEDUPLIKASI
# ============================================================================

def _make_dedup_key(record: dict) -> str:
    """
    Key berdasarkan: tanggal (YYYY-MM-DD) + set ticker + sector.
    Dua prediksi dianggap duplikat jika dibuat di hari yang sama
    dengan set ticker yang sama persis.
    """
    created = _parse_iso(record.get("created_at", ""))
    date_str = created.strftime("%Y-%m-%d") if created else "unknown"
    tickers = sorted(
        p.get("ticker", "") for p in record.get("projections", []) if p.get("ticker")
    )
    return f"{date_str}::{'|'.join(tickers)}"


# ============================================================================
# KOMPONEN UTAMA
# ============================================================================

class PredictionTracker(Component):
    display_name = "Prediction Tracker (Stage 3)"
    description = (
        "Menyimpan prediksi Stage 2, mengevaluasi akurasi setelah horizon tercapai, "
        "dan menghasilkan laporan performa + metrics kalibrasi. "
        "Multi-source price fallback (Yahoo → Stooq → Alpha Vantage). "
        "Dedup harian untuk mencegah duplikasi."
    )
    icon = "history"

    inputs = [
        DataInput(
            name="projection_data",
            display_name="Projection Data (Stage 2)",
            info="Output 'Projection Data (JSON)' dari Quantitative Projector.",
            required=False,
        ),
        StrInput(
            name="mode",
            display_name="Mode",
            info="record | evaluate | report | auto",
            value="auto",
            required=True,
        ),
        StrInput(
            name="storage_path",
            display_name="Storage Path",
            value=_DEFAULT_STORAGE,
            required=True,
        ),
        IntInput(
            name="min_horizon_days",
            display_name="Min Horizon Days",
            value=5,
            required=True,
        ),
        StrInput(
            name="alpha_vantage_api_key",
            display_name="Alpha Vantage API Key",
            info="Free tier: 25 request/hari. Digunakan hanya jika Yahoo & Stooq gagal.",
            value="EHK2XUH0OMKS34UZ",
            required=False,
        ),
        StrInput(
            name="dedup_mode",
            display_name="Dedup Mode",
            info="none | daily_replace | daily_skip",
            value="daily_replace",
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="Report", name="report", method="build_report"),
        Output(display_name="Metrics Data (JSON)", name="metrics", method="build_metrics"),
    ]

    def build_report(self) -> Message:
        return Message(text=self._cached_run()["report_md"])

    def build_metrics(self) -> Data:
        return Data(data=self._cached_run()["metrics_data"])

    def _cached_run(self) -> dict:
        if not hasattr(self, "_cache") or self._cache is None:
            self._cache = self._run()
        return self._cache

    # ------------------------------------------------------------------
    def _quota_path(self) -> str:
        # Quota file diletakkan di samping storage file
        base = Path(self.storage_path).parent
        return str(base / ".langflow_alphavantage_quota.json")

    def _run(self) -> dict:
        mode = (self.mode or "auto").strip().lower()
        store = _load_store(self.storage_path)
        actions: list[str] = []

        if mode in ("record", "auto"):
            n, dedup_info = self._record(store)
            if n:
                actions.append(f"Recorded {n} projection(s).")
            if dedup_info:
                actions.append(dedup_info)

        if mode in ("evaluate", "auto"):
            n, price_stats = self._evaluate(store)
            if n:
                actions.append(f"Evaluated {n} prediction(s).")
            if price_stats:
                actions.append(price_stats)

        store["metrics"] = self._recompute_metrics(store)
        _save_store(self.storage_path, store)

        report_md = self._render_report(store, actions)
        return {
            "report_md": report_md,
            "metrics_data": {
                "metrics": store["metrics"],
                "predictions_count": len(store["predictions"]),
                "evaluated_count": sum(
                    1 for p in store["predictions"] if p.get("evaluation")
                ),
                "generated_at": _now_iso(),
                "storage_path": self.storage_path,
            },
        }

    # ------------------------------------------------------------------
    # RECORD (dengan dedup & multi-source fallback)
    # ------------------------------------------------------------------
    def _record(self, store: dict) -> tuple[int, str]:
        data = self.projection_data
        if isinstance(data, Data):
            data = data.data
        if isinstance(data, str):
            try:
                data = json.loads(data)
            except json.JSONDecodeError:
                return 0, ""
        if not isinstance(data, dict):
            return 0, ""

        projs = data.get("projections") or []
        if not projs:
            return 0, ""

        # Enrich dengan entry_price (multi-source)
        enriched = []
        source_counts = {"yahoo": 0, "stooq": 0, "alpha_vantage": 0, "none": 0}
        for p in projs:
            ticker = p.get("ticker")
            if not ticker:
                continue
            # Gunakan entry_price dari Stage 2 jika ada, kalau tidak fetch ulang
            entry_price = p.get("entry_price")
            if entry_price is None:
                entry_price, source = fetch_price_with_fallback(
                    ticker, self.alpha_vantage_api_key, self._quota_path(),
                )
                source_counts[source] = source_counts.get(source, 0) + 1
            else:
                source_counts["yahoo"] = source_counts.get("yahoo", 0) + 1

            enriched.append({
                "ticker": ticker,
                "direction": p.get("direction"),
                "point_move_pct": p.get("point_move_pct"),
                "ci_80_low_pct": p.get("ci_80_low_pct"),
                "ci_80_high_pct": p.get("ci_80_high_pct"),
                "horizon_days": p.get("horizon_days", 2),
                "sector": p.get("sector"),
                "bucket": p.get("bucket"),
                "entry_price": entry_price,
            })

        if not enriched:
            return 0, ""

        new_record = {
            "id": uuid.uuid4().hex[:12],
            "created_at": _now_iso(),
            "signal_strength": data.get("signal_strength"),
            "market_summary": data.get("market_summary"),
            "horizon_days": max(p.get("horizon_days", 2) for p in enriched),
            "projections": enriched,
            "evaluation": None,
        }

        # ---- DEDUP LOGIC ----
        dedup_info = ""
        dedup_mode = (self.dedup_mode or "daily_replace").strip().lower()
        new_key = _make_dedup_key(new_record)

        existing_idx = None
        for idx, rec in enumerate(store["predictions"]):
            if rec.get("evaluation"):
                continue  # jangan ganggu yang sudah dievaluasi
            if _make_dedup_key(rec) == new_key:
                existing_idx = idx
                break

        if existing_idx is not None and dedup_mode != "none":
            if dedup_mode == "daily_skip":
                return 0, f"Skipped (dedup: existing prediction on same day)."
            elif dedup_mode == "daily_replace":
                store["predictions"][existing_idx] = new_record
                dedup_info = "Replaced existing prediction (same day + ticker set)."

        if existing_idx is None or dedup_mode == "none":
            store["predictions"].append(new_record)

        if len(store["predictions"]) > 500:
            store["predictions"] = store["predictions"][-500:]

        _save_store(self.storage_path, store)

        # Info sumber harga
        src_summary = ", ".join(
            f"{k}={v}" for k, v in source_counts.items() if v > 0
        )
        if src_summary:
            dedup_info = (dedup_info + " " if dedup_info else "") + f"Price sources: {src_summary}."

        return len(enriched), dedup_info

    # ------------------------------------------------------------------
    # EVALUATE
    # ------------------------------------------------------------------
    def _evaluate(self, store: dict) -> tuple[int, str]:
        now = datetime.now(timezone.utc)
        evaluated_count = 0
        source_counts = {"yahoo": 0, "stooq": 0, "alpha_vantage": 0, "none": 0}

        for record in store["predictions"]:
            if record.get("evaluation"):
                continue
            created = _parse_iso(record.get("created_at", ""))
            if created is None:
                continue
            horizon = max(self.min_horizon_days, int(record.get("horizon_days", 2)))
            if now < created + timedelta(days=horizon):
                continue

            per_ticker = []
            for p in record.get("projections", []):
                ticker = p.get("ticker")
                entry = p.get("entry_price")
                if not ticker or not entry:
                    continue
                exit_price, source = fetch_price_with_fallback(
                    ticker, self.alpha_vantage_api_key, self._quota_path(),
                )
                source_counts[source] = source_counts.get(source, 0) + 1
                if exit_price is None:
                    continue

                actual_pct = (exit_price / entry - 1.0) * 100.0
                predicted_pct = p.get("point_move_pct", 0.0)
                error = actual_pct - predicted_pct

                predicted_dir = 1 if predicted_pct > 0 else -1
                actual_dir = 1 if actual_pct > 0 else -1

                lo = p.get("ci_80_low_pct", -999)
                hi = p.get("ci_80_high_pct", 999)

                per_ticker.append({
                    "ticker": ticker,
                    "sector": p.get("sector"),
                    "predicted_pct": round(predicted_pct, 3),
                    "actual_pct": round(actual_pct, 3),
                    "error": round(error, 3),
                    "abs_error": round(abs(error), 3),
                    "direction_hit": predicted_dir == actual_dir,
                    "in_ci_80": lo <= actual_pct <= hi,
                    "entry_price": entry,
                    "exit_price": exit_price,
                })

            if not per_ticker:
                continue

            record["evaluation"] = {
                "evaluated_at": _now_iso(),
                "horizon_days": horizon,
                "per_ticker": per_ticker,
            }
            evaluated_count += 1

        if evaluated_count > 0:
            _save_store(self.storage_path, store)

        stats = ""
        total = sum(source_counts.values())
        if total > 0:
            stats = "Eval sources: " + ", ".join(
                f"{k}={v}" for k, v in source_counts.items() if v > 0
            ) + "."
        return evaluated_count, stats

    # ------------------------------------------------------------------
    # METRICS (sama seperti sebelumnya)
    # ------------------------------------------------------------------
    def _recompute_metrics(self, store: dict) -> dict:
        all_t: list[dict] = []
        for rec in store["predictions"]:
            ev = rec.get("evaluation")
            if not ev:
                continue
            for t in ev.get("per_ticker", []):
                t["signal_strength"] = rec.get("signal_strength")
                all_t.append(t)

        if not all_t:
            return {
                "total_evaluated": 0,
                "mean_absolute_error": None,
                "direction_hit_rate": None,
                "ci_coverage_rate": None,
                "by_signal_strength": {},
                "by_sector": {},
            }

        mae = statistics.fmean(t["abs_error"] for t in all_t)
        hit_rate = sum(1 for t in all_t if t["direction_hit"]) / len(all_t)
        ci_rate = sum(1 for t in all_t if t["in_ci_80"]) / len(all_t)

        by_ss: dict[str, list[dict]] = {}
        for t in all_t:
            ss = t.get("signal_strength")
            if ss is None:
                continue
            by_ss.setdefault(self._ss_bucket(int(ss)), []).append(t)

        by_sector: dict[str, list[dict]] = {}
        for t in all_t:
            by_sector.setdefault(t.get("sector") or "Unknown", []).append(t)

        return {
            "total_evaluated": len(all_t),
            "mean_absolute_error": round(mae, 3),
            "direction_hit_rate": round(hit_rate, 3),
            "ci_coverage_rate": round(ci_rate, 3),
            "by_signal_strength": {
                b: {
                    "n": len(items),
                    "mae": round(statistics.fmean(x["abs_error"] for x in items), 3),
                    "hit_rate": round(
                        sum(1 for x in items if x["direction_hit"]) / len(items), 3
                    ),
                    "ci_coverage": round(
                        sum(1 for x in items if x["in_ci_80"]) / len(items), 3
                    ),
                }
                for b, items in by_ss.items()
            },
            "by_sector": {
                s: {
                    "n": len(items),
                    "mae": round(statistics.fmean(x["abs_error"] for x in items), 3),
                    "hit_rate": round(
                        sum(1 for x in items if x["direction_hit"]) / len(items), 3
                    ),
                }
                for s, items in by_sector.items()
            },
        }

    @staticmethod
    def _ss_bucket(ss: int) -> str:
        if ss >= 9:
            return "9-10 (Very Strong)"
        if ss >= 7:
            return "7-8 (Strong)"
        if ss >= 4:
            return "4-6 (Moderate)"
        return "1-3 (Weak)"

    # ------------------------------------------------------------------
    # REPORT (sama seperti sebelumnya, sedikit tambahan info quota)
    # ------------------------------------------------------------------
    def _render_report(self, store: dict, actions: list[str]) -> str:
        m = store.get("metrics", {})
        lines = ["# 🔁 Feedback Loop — Accuracy Report", ""]
        lines.append(f"_Generated: {_now_iso()}_")
        lines.append("")

        if actions:
            lines.append("**Actions:** " + " | ".join(actions))
            lines.append("")

        # Info kuota Alpha Vantage
        _, quota = _check_quota(self._quota_path())
        lines.append(
            f"**Alpha Vantage quota:** {quota['count']}/{_ALPHA_VANTAGE_DAILY_LIMIT} used today."
        )
        lines.append("")

        total = m.get("total_evaluated", 0)
        if total == 0:
            lines.append("⚠️ Belum ada prediksi yang dievaluasi.")
            lines.append("")
            lines.append("Cara pakai:")
            lines.append("- Jalankan workflow ini setiap hari.")
            lines.append("- Prediksi akan dievaluasi setelah horizon tercapai.")
            lines.append(f"- Storage: `{self.storage_path}`")
            return "\n".join(lines)

        mae = m.get("mean_absolute_error")
        hit = m.get("direction_hit_rate")
        ci = m.get("ci_coverage_rate")

        lines.append("## Overall Metrics")
        lines.append("")
        lines.append("| Metric | Value | Interpretation |")
        lines.append("|--------|-------|----------------|")
        lines.append(f"| **Mean Absolute Error** | {mae}% | < 2% = sangat baik |")
        lines.append(f"| **Direction Hit Rate** | {hit:.1%} | > 55% = punya edge |")
        lines.append(f"| **CI 80% Coverage** | {ci:.1%} | Idealnya ≈ 80% |")
        lines.append(f"| **Total Evaluated** | {total} | — |")
        lines.append("")

        by_ss = m.get("by_signal_strength", {})
        if by_ss:
            lines.append("## Accuracy by Signal Strength")
            lines.append("")
            lines.append("| Signal Strength | N | MAE | Hit Rate | CI Coverage |")
            lines.append("|-----------------|---|-----|----------|-------------|")
            for b in sorted(by_ss.keys(), reverse=True):
                x = by_ss[b]
                lines.append(
                    f"| {b} | {x['n']} | {x['mae']}% | "
                    f"{x['hit_rate']:.1%} | {x['ci_coverage']:.1%} |"
                )
            lines.append("")

        by_sec = m.get("by_sector", {})
        if by_sec:
            lines.append("## Accuracy by Sector")
            lines.append("")
            lines.append("| Sector | N | MAE | Hit Rate |")
            lines.append("|--------|---|-----|----------|")
            for s in sorted(by_sec.keys(), key=lambda k: -by_sec[k]["n"]):
                x = by_sec[s]
                lines.append(f"| {s} | {x['n']} | {x['mae']}% | {x['hit_rate']:.1%} |")
            lines.append("")

        recent = [r for r in store["predictions"] if r.get("evaluation")][-3:]
        if recent:
            lines.append("## Recent Evaluated Predictions")
            lines.append("")
            for rec in reversed(recent):
                ev = rec["evaluation"]
                lines.append(f"### `{rec['id']}` — {rec['created_at'][:10]}")
                lines.append(f"- Signal: **{rec.get('signal_strength', 'N/A')}** | Horizon: {ev.get('horizon_days')}d")
                lines.append("")
                lines.append("| Ticker | Predicted | Actual | Error | Dir | CI |")
                lines.append("|--------|-----------|--------|-------|-----|-----|")
                for t in ev["per_ticker"][:6]:
                    lines.append(
                        f"| {t['ticker']} | {t['predicted_pct']:+.2f}% | "
                        f"{t['actual_pct']:+.2f}% | {t['error']:+.2f}% | "
                        f"{'✅' if t['direction_hit'] else '❌'} | "
                        f"{'✅' if t['in_ci_80'] else '❌'} |"
                    )
                lines.append("")

        lines.append("---")
        lines.append("")
        lines.append("## Interpretation")
        lines.append("")
